package agent

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	frpclient "github.com/fatedier/frp/client"
	"github.com/fatedier/frp/pkg/config"
	"github.com/fatedier/frp/pkg/config/source"
	v1 "github.com/fatedier/frp/pkg/config/v1"
	"github.com/fatedier/frp/pkg/config/v1/validation"
	"github.com/fatedier/frp/pkg/policy/security"
	frplog "github.com/fatedier/frp/pkg/util/log"
)

// The embedded frpc runs the frp client library in-process, one service per
// frps node, using the frpc.toml generated by meshportd (GET /me/frpc). On a
// frp.config push it fetches again and hot-reloads proxies; a changed common
// section (server address, token) restarts that node's service.

type frpcService struct {
	nodeID  string
	node    string
	common  string // TOML before the first [[proxies]]
	toml    string
	svc     *frpclient.Service
	cancel  context.CancelFunc
	proxies []string
	started time.Time
	runErr  string
}

type frpcManager struct {
	a       *Agent
	mu      sync.Mutex
	reload_ sync.Mutex
	svcs    map[string]*frpcService
	logOnce sync.Once
	lastErr string
}

func newFRPCManager(a *Agent) *frpcManager {
	return &frpcManager{a: a, svcs: map[string]*frpcService{}}
}

type frpcItem struct {
	NodeID string `json:"node_id"`
	Node   string `json:"node"`
	TOML   string `json:"toml"`
	Active int    `json:"active_proxies"`
}

func splitCommon(toml string) string {
	if i := strings.Index(toml, "\n[[proxies]]"); i >= 0 {
		return toml[:i]
	}
	return toml
}

// reload fetches the generated configuration and applies it.
func (m *frpcManager) reload(ctx context.Context) error {
	m.reload_.Lock()
	defer m.reload_.Unlock()
	if !m.a.st.get().Settings.FRPC {
		m.stopAll()
		return nil
	}
	if m.a.myID() == "" {
		return nil
	}
	var out struct {
		Items []frpcItem `json:"items"`
	}
	if err := m.a.api(ctx, "GET", "/me/frpc", nil, &out); err != nil {
		m.setErr(err.Error())
		return err
	}
	m.logOnce.Do(func() {
		frplog.InitLogger(filepath.Join(m.a.opt.DataDir, "frpc.log"), "info", 3, true)
	})
	want := map[string]bool{}
	var errs []string
	for _, it := range out.Items {
		if it.Active == 0 {
			continue
		}
		want[it.NodeID] = true
		if err := m.apply(it); err != nil {
			errs = append(errs, it.Node+": "+err.Error())
			m.a.log.Warn("frpc apply", "node", it.Node, "err", err)
		}
	}
	m.mu.Lock()
	var stale []*frpcService
	for id, s := range m.svcs {
		if !want[id] {
			stale = append(stale, s)
			delete(m.svcs, id)
		}
	}
	m.mu.Unlock()
	for _, s := range stale {
		s.stop()
		m.a.log.Info("frpc stopped", "node", s.node)
	}
	m.setErr(strings.Join(errs, "; "))
	m.a.events.publish("frpc", m.status())
	return nil
}

func (m *frpcManager) setErr(e string) {
	m.mu.Lock()
	m.lastErr = e
	m.mu.Unlock()
}

func (m *frpcManager) apply(it frpcItem) error {
	m.mu.Lock()
	cur := m.svcs[it.NodeID]
	m.mu.Unlock()
	if cur != nil && cur.toml == it.TOML {
		return nil
	}
	path := filepath.Join(m.a.opt.DataDir, "frpc", safeName(it.NodeID)+".toml")
	if err := os.WriteFile(path, []byte(it.TOML), 0o600); err != nil {
		return err
	}
	res, err := config.LoadClientConfigResult(path, false)
	if err != nil {
		return fmt.Errorf("設定解析失敗：%w", err)
	}
	res.Common.Log.To = filepath.Join(m.a.opt.DataDir, "frpc.log")
	res.Common.Log.DisablePrintColor = true
	names := make([]string, 0, len(res.Proxies))
	for _, p := range res.Proxies {
		names = append(names, p.GetBaseConfig().Name)
	}
	sort.Strings(names)
	common := splitCommon(it.TOML)

	if cur != nil && cur.common == common && cur.svc != nil {
		// hot reload: same server, new proxy set
		if err := cur.svc.UpdateConfigSource(res.Common, res.Proxies, res.Visitors); err != nil {
			return fmt.Errorf("熱重載失敗：%w", err)
		}
		m.mu.Lock()
		cur.toml, cur.proxies = it.TOML, names
		m.mu.Unlock()
		m.a.log.Info("frpc reloaded", "node", it.Node, "proxies", len(names))
		return nil
	}
	if cur != nil {
		cur.stop()
	}
	unsafe := security.NewUnsafeFeatures(nil)
	src := source.NewConfigSource()
	if err := src.ReplaceAll(res.Proxies, res.Visitors); err != nil {
		return err
	}
	agg := source.NewAggregator(src)
	proxies, visitors, err := agg.Load()
	if err != nil {
		return err
	}
	proxies, visitors = config.FilterClientConfigurers(res.Common, proxies, visitors)
	proxies = config.CompleteProxyConfigurers(proxies)
	visitors = config.CompleteVisitorConfigurers(visitors)
	if _, err := validation.ValidateAllClientConfig(res.Common, proxies, visitors, unsafe); err != nil {
		return fmt.Errorf("設定驗證失敗：%w", err)
	}
	svc, err := frpclient.NewService(frpclient.ServiceOptions{Common: res.Common, ConfigSourceAggregator: agg, UnsafeFeatures: unsafe, ConfigFilePath: path})
	if err != nil {
		return err
	}
	ctx, cancel := context.WithCancel(m.a.ctx)
	s := &frpcService{nodeID: it.NodeID, node: it.Node, common: common, toml: it.TOML, svc: svc, cancel: cancel, proxies: names, started: time.Now()}
	m.mu.Lock()
	m.svcs[it.NodeID] = s
	m.mu.Unlock()
	go func() {
		err := svc.Run(ctx)
		if err != nil && ctx.Err() == nil {
			m.mu.Lock()
			s.runErr = err.Error()
			m.mu.Unlock()
			m.a.log.Warn("frpc exited", "node", it.Node, "err", err)
			m.a.events.publish("frpc", m.status())
		}
	}()
	m.a.log.Info("frpc started", "node", it.Node, "server", res.Common.ServerAddr, "proxies", len(names))
	return nil
}

func (s *frpcService) stop() {
	if s.cancel != nil {
		s.cancel()
	}
	if s.svc != nil {
		s.svc.Close()
	}
}

func (m *frpcManager) stopAll() {
	m.mu.Lock()
	all := m.svcs
	m.svcs = map[string]*frpcService{}
	m.mu.Unlock()
	for _, s := range all {
		s.stop()
	}
	if len(all) > 0 {
		m.a.events.publish("frpc", m.status())
	}
}

type FRPCProxyStatus struct {
	Name       string `json:"name"`
	Type       string `json:"type"`
	Phase      string `json:"phase"` // running | wait start | start error | check failed | closed ...
	Err        string `json:"err,omitempty"`
	RemoteAddr string `json:"remote_addr,omitempty"`
}

type FRPCNodeStatus struct {
	NodeID  string            `json:"node_id"`
	Node    string            `json:"node"`
	Started int64             `json:"started"`
	Error   string            `json:"error,omitempty"`
	Proxies []FRPCProxyStatus `json:"proxies"`
}

type FRPCStatus struct {
	Enabled bool             `json:"enabled"`
	Error   string           `json:"error,omitempty"`
	Nodes   []FRPCNodeStatus `json:"nodes"`
}

func (m *frpcManager) status() FRPCStatus {
	m.mu.Lock()
	defer m.mu.Unlock()
	st := FRPCStatus{Enabled: m.a.st.get().Settings.FRPC, Error: m.lastErr, Nodes: []FRPCNodeStatus{}}
	for _, s := range m.svcs {
		ns := FRPCNodeStatus{NodeID: s.nodeID, Node: s.node, Started: s.started.UnixMilli(), Error: s.runErr, Proxies: []FRPCProxyStatus{}}
		exp := s.svc.StatusExporter()
		for _, name := range s.proxies {
			ps := FRPCProxyStatus{Name: name, Phase: "wait start"}
			if ws, ok := exp.GetProxyStatus(name); ok && ws != nil {
				ps.Type, ps.Phase, ps.Err, ps.RemoteAddr = ws.Type, ws.Phase, ws.Err, ws.RemoteAddr
			}
			ns.Proxies = append(ns.Proxies, ps)
		}
		st.Nodes = append(st.Nodes, ns)
	}
	sort.Slice(st.Nodes, func(i, j int) bool { return st.Nodes[i].Node < st.Nodes[j].Node })
	return st
}

func (m *frpcManager) summary() string {
	st := m.status()
	var b strings.Builder
	for _, n := range st.Nodes {
		fmt.Fprintf(&b, "%s:", n.Node)
		for _, p := range n.Proxies {
			fmt.Fprintf(&b, " %s=%s", p.Name, p.Phase)
		}
		b.WriteString("\n")
	}
	if b.Len() == 0 {
		return "no active proxies"
	}
	return strings.TrimSpace(b.String())
}

var _ = v1.ClientCommonConfig{}
